package coupons;
import coupons.ReceiptObservations.*;
import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class PromotionQualificationTest {
    CouponTransaction tx(){var tx=new CouponTransaction(new ReceiptTotals(BigDecimal.ZERO,new BigDecimal("30")));tx.addPurchaseItem(new PurchaseItem("Shampoo","same-sku",new BigDecimal("10"),new BigDecimal("10"),1));tx.addPurchaseItem(new PurchaseItem("Shampoo","same-sku",new BigDecimal("10"),new BigDecimal("10"),2));return tx;}
    Earning offer(CouponTransaction tx,PromotionType type,String threshold,SpendBasis basis){return new Earning(UUID.randomUUID(),EarningKind.WALGREENS_CASH,"Walgreens","Offer",Scope.MULTI_ITEM,tx.getPurchaseItems().stream().map(PurchaseItem::getLineItemId).toList(),new RebateBenefit(BenefitKind.STORE_REWARD,new BigDecimal("5"),Currency.getInstance("USD"),"Walgreens"),null,RebateStatus.EXPECTED,null,null,null,List.of(),null,new OfferRequirement(type,new BigDecimal(threshold),null,basis),null);}
    @Test void countsPurchasedUnitsAcrossSeparateLines(){var tx=tx();var result=PromotionQualification.evaluate(offer(tx,PromotionType.BUY,"3",SpendBasis.UNKNOWN),tx);assertEquals("MET",result.status());assertEquals(3,result.qualifyingQuantity());assertEquals("NOT_MET",PromotionQualification.evaluate(offer(tx,PromotionType.BUY,"4",SpendBasis.UNKNOWN),tx).status());}
    @Test void spendThresholdUsesRecordedCouponBasis(){var tx=tx();var lines=tx.getPurchaseItems().stream().map(PurchaseItem::getLineItemId).toList();var discount=new CouponApplied(UUID.randomUUID(),"MFG",new BigDecimal("12"),lines,null,false);tx.addAppliedCoupon(discount);tx.setObservations(new ReceiptObservations(null,null,List.of(),List.of(),null,List.of(),Map.of(discount.getApplicationId(),DiscountKind.MANUFACTURER)));assertEquals("MET",PromotionQualification.evaluate(offer(tx,PromotionType.SPEND,"20",SpendBasis.SALE_BEFORE_COUPONS),tx).status());var after=PromotionQualification.evaluate(offer(tx,PromotionType.SPEND,"20",SpendBasis.SALE_AFTER_COUPONS),tx);assertEquals("NOT_MET",after.status());assertEquals(0,after.qualifyingSpend().compareTo(new BigDecimal("18")));}
    @Test void noImplicitWholeReceiptEligibility(){var tx=tx();var e=offer(tx,PromotionType.SPEND,"20",SpendBasis.SALE_BEFORE_COUPONS);var whole=new Earning(e.earningId(),e.kind(),e.provider(),e.offerReference(),Scope.RECEIPT,List.of(),e.expected(),null,e.status(),null,null,null,List.of(),null,e.requirement(),null);assertEquals("CANNOT_VERIFY",PromotionQualification.evaluate(whole,tx).status());}
}
